"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["7489"],{6549(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>m,assets:()=>l});var o=JSON.parse('{"id":"reference/monitor/howtos/systemView","title":"System View","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/monitor/howtos/systemView.md","sourceDirName":"reference/monitor/howtos","slug":"/reference/monitor/howtos/systemView","permalink":"/personal-av-docs/docs/reference/monitor/howtos/systemView","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/monitor/howtos/systemView.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"System View","sidebar_label":"System View","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/monitor/howtos/systemView","format":"md"}}'),i=n(4848),a=n(8453);let s={title:"System View",sidebar_label:"System View",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/monitor/howtos/systemView",format:"md"},r,l={},m=[];function d(e){let t={a:"a",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:[":::note Edition\n",(0,i.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/monitor/howtos/systemView",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsx)(t.p,{children:"System View\nThe most recent activity from the system is available from the system details screen.\nThis page provides access into the system communications history as well as router configuration using ACEmanager (by clicking the IP address) or AirLink OS (by clicking the\nConfiguration\nbutton) and other functions.\nInitializing Table Of Contents...\nConfiguration\nYou can check the configuration of the system from last synchronization, launch a synchronize operation, create a new template from the system configuration, or directly change the configuration settings on this system (apply settings).\nDevice Management actions\nThe following actions can be run on the system, depending on the capabilities of the system:\nSynchronize\nCreate a synchronization operation; the server will read all the data known for this system next time the system communicates.\nConfigure Communication\nChange heartbeat and periodic reports.\nReboot\nReboot the system.\nUpgrade Firmware\nUpgrade the system with new firmware.\nApply Template\nApply an already created template.\nEdit\nEdit the system details.\nChange labels\nAdd labels to the system or remove labels from the system.\nActivate\nActivate the system if it is in Maintenance or Inventory.\nExport data history\nExport a .csv file containing information in AirVantage for a single system.\nExport last data\nExport a .csv file containing the last known information in AirVantage for multiple systems.\nCustom Command\nSend a command to a system. Commands must be defined in one of the applications running in your system.\nSend SMS\nSend a SMS. A SMS account needs to be configured for your company. See\nHow to configure an SMS account?\nfor help.\nWake Up\nSend a wakeup SMS. A SMS account needs to be configured for your company. This function is supported only on OpenAT AirPrime module.\nFactory reset\nRestore the system to its factory settings.\nRetrieve > Device data\nRetrieve a dataset from the device.\nRetrieve > System logs\nRetrieve and then download logs from the device. See\nHow to retrieve logs from a system?\nfor help.\nSend AT Command\nThis function is supported only on OpenAT AirPrime modules.\nInstall Application\nInstall or upgrade an embedded application on your system.\nInstall Bundle\nFor systems that use Legato, install a system bundle on your system. See\nCreate Systems Bundles\non the Legato web site for help.\nTimeline\nTo view the Timeline, click the Timeline button.\nThe Timeline presents a chronological list view of the events in the device\u2019s life:\nCommunication (start & end session, data publication)\nOperations (commands, \u2026) & updates (system edition on AirVantage) applied on the system\nAlerts occurred\nUsages (start & end connectivity session, \u2026)\nin order to see foreseeable relation between an issue and any event.\nThe filtering mechanism enables you to get only the relevant information, and time navigation enables you to browse the timeline.\nData History\nTo view the Data History, click the Data History button.\nYou can configure the Data History to present a graphical view of the communications history.\nIt has to be customized to show the information that is of interest to you\nA widget provides statistics about the evolution over time of the cellular technology reported by the device: LTE, HSPA, 3G or 2G. This new widget gives working conditions of your device in the field.\nData history widgets can also be added in the system details view.\nConfigurable Dashboard\nYou can view the Initial Dashboard, with its set of default widgets, or create a Custom Dashboard with a set of widgets to display the information that is most important for you.\nSee\nhere\nfor more information about dashboard.\nThe standard widgets displayed on the Initial Dashboard are:\nSystem Communication\nSystem Info\nInvoiced Data Usage\nOperations\nSystem Carrier\nLast Communication\nAlerts\nCumulative invoiced data usage\nSystem Applications\nProvisioning Options\nCumulative SMS\nLocation\nData Sessions per day\nMain Life Cycle Dates\nYou can also add the following widgets to a custom dashboard:\nInterface Statistics\nLatest Usages\nAirtime usage (operator information)\nAirtime usage (device estimation)\nAlert State\nAlert History\nAlert List\nFirmware Components\nData History\nData List\nLast Data Received\nCombo Chart\nGauge Chart\nSingle Value Chart\nCommand Widget\nData History Table\nText Widget\nCumulative USSD\nRoaming capabilities\nSystem Data Usage\nConnected Devices\nSystem Communication\nThis widget shows the communication information of the system with AirVantage:\nCommunication status: green, amber, red. Mouseover will give you the way AirVantage is configured to monitor the system.\nLast communication date: time of the most recent communication of the system to AirVantage, and estimated time of next communication based on the system heartbeat configuration.\nSynchronization status: shows events raised by AirVantage during last synchronization. Information like IP @, SIM, firmware change are logged here. Click the icon to display the Synchronization Logs.\nExample of Synchronization Logs\nSystem information\nThe System information (\u201CSystem Info\u201D) widget shows the latest information retrieved from the system:\nLatest firmware\nIdentifiers of the Gateway and the SIM: IMEI, Serial number, IMSI or ICCID, Phone number (MSISDN)\nLast template applied with AirVantage, if any\nStatus report information (see\nhere\nto check the list of parameters in the default status report)\nColor Codes for data values:\nSystem information may appear in different colors depending on the status of the data\nRed\nwhen a Status Report exists, is activated (ON) and the timestamp when the value was received is greater than the Status report period.\nGreen or blue\nwhen a Status Report exists, is activated (ON) and the timestamp when the value was received is lower than or equal to the Status report period.\nOrange\nwhen the router reports data that does not match the data linked to the router. For example, if the\nFirmware\nfield appears orange, the router may be linked to a different firmware version than the version that is installed and being reported to ALMS. If this Firmware issue occurs, you can correct it by editing the system information. Click the\nMore\nbutton, select\nEdit\n, and then select the correct firmware version in\nFirmware and Applications\n.\nGray\nwhen no Status Report is configured or when it is in OFF status.\nALEOS-based Systems\nIf your system runs ALEOS, you can jump to\nACEmanager\nfrom system details by clicking on its IP address in the default status info report section.\nNote\n: Works only if the IP address is reachable from the user network and if the system is communicating.\nAirLink OS-based Systems\nFor AirLink XR90 and XR80 routers, the System Info widget shows information for each cellular interface on the router. Click one of the tabs (\nCellular\n,\nAirLink XR80\n, or\nXP Cellular\nin the example shown below) to view information about an interface.\nAn RX55 router running AirLink OS has just one cellular interface, so no tabs appear on its System Info widget.\nMulti-APN\nIf a cellular interface has multiple APNs configured, click the\nMulti-APN Enabled\nlink to view details for each APN, as shown below.\nMulti-APN details are available only for routers running AirLink OS 4.0 or later.\nExternal Modem\nIf the router has one or more High Power User Equipment (HPUE) modems connected via Ethernet, the modem information is available on the System Info widget.\nExternal Modem details are available only for routers running AirLink OS 4.1 or later.\nNote that some HPUE modems may not report their IPv6 WAN addresses to the router. As a result, the IPv6 addresses may not be included in AMR reports. The flow of IPv6 traffic itself is not affected.\nThe widget can display data for up to six external modems.\nIf the router does not report any external modem data points within the 4 minutes after a manual synchronization operation is completed or within the 4 minutes after the router is supposed to report in for the status report, the external modem is considered disconnected and is not displayed in the System Info widget.\nSystem Alerts widget\nThe widget shows the latest alerts raised for this sytem and provides links to acknowledge it or show the complete list.\nLatest Operations widget\nThe widget shows the latest operations executed or scheduled for this sytem and provides links to access more details (like logs) or show the complete list.\nLocation widget\nThe widget shows the system location on a Google Map. You can edit the location manually if your system is not moving.\nInterface Statistics widget\nFor routers running AirLink OS 4.0 or later, this widget mirrors the \u201CStatistics\u201D page in AirLink OS (Status/Monitoring > Networking > Statistics), displaying the interface name as well as the number of Bytes, Packets and Errors sent and received for that interface.\nApplications list\nThe widget lists the applications running on the system and actions you can perform on each application.\nFeature\nIcon\nDescription\nDetails\nSee the applications definition and capabilities, download application package.\nApplication\nOpen the application configuration page: view the last data, settings and change the configuration.\nUpgrade\nLaunch an operation to upgrade the application on the system.\nStart\nLaunch an operation to start the application on the system.\nStop\nLaunch an operation to stop the application on the system.\nUninstall\nLaunch an operation to uninstall the application on the system."})]})}function c(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var o=n(6540);let i={},a=o.createContext(i);function s(e){let t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);